                            Q.append(v)

                # Pick alternate levels
                for i in range(0, len(level_nodes), 2):
                    if len(result) + 1 >= target_size:
                        break
                    result.append(level_nodes[i])

        if len(result) < target_size:
            # Fallback: better selection
            visited = [False] * (n + 1)
            result = []

            for i in range(1, n + 1):
                if not visited[i]:
