def sphere_2points(p1, p2):
    center = ((p1[0]+p2[0])/2.0, (p1[1]+p2[1])/2.0, (p1[2]+p2[2])/2.0)
    r_sq = dist_sq(center, p1)
    return center, r_sq

def matrix_solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for i in range(n):
        max_row = abs(M[i][i])
        for j in range(i+1, n):
            if abs(M[j][i]) > max_row:
                max_row = abs(M[j][i])
                M[i], M[j] = M[j], M[i]
        if abs(M[i][i]) < 1e-12:
            continue
        for j in range(i, n+1):
            M[i][j] /= M[i][i]
        for k in range(n):
            if k != i:
                for j in range(n+1):
                    M[k][j] -= M[k][i] * M[i][j]
    return [M[i][n] for i in range(n)]

def sphere_from_4points(p1, p2, p3, p4):
    A = [
        [2*(p2[0]-p1[0]), 2*(p2[1]-p1[1]), 2*(p2[2]-p1[2])],
