        p2[0]**2 - p1[0]**2 + p2[1]**2 - p1[1]**2 + p2[2]**2 - p1[2]**2,
        p3[0]**2 - p1[0]**2 + p3[1]**2 - p1[1]**2 + p3[2]**2 - p1[2]**2,
        p4[0]**2 - p1[0]**2 + p4[1]**2 - p4[1]**2 + p4[2]**2 - p1[2]**2
    ]
    center = matrix_solve(A, B)
    return tuple(center), dist_sq(tuple(center), p1)

def is_inside(center, r_sq, point, eps=1e-8):
    return dist_sq(center, point) <= r_sq + eps

def all_inside(center, r_sq, pts, p, eps=1e-8):
    for pt in pts:
        if dist_sq(center, pt) > r_sq + eps:
            return False
    if dist_sq(center, p) > r_sq + eps:
        return False
    return True

def welzl(pts, boundary=[]):
    if not pts or len(boundary) == 4:
