import sys

def count_independent_sets(n, adj):
    """Count independent sets efficiently using recursion with memoization"""
    memo = {}

    def count(adj, n, start):
        if start == n:
            return 1

        key = (tuple(adj), start)
        if key in memo:
            return memo[key]

        result = count(adj, n, start + 1)

        # Try including vertex start
        neighbors = adj[start]
        include = True
        for v in range(start + 1, n):
            if (neighbors >> v) & 1:
                include = False
                break

        if include:
            result += count(adj, n, start + 1)

        memo[key] = result
        return result

    return count(adj, n, 0)

def solve_graph(n, edges):
    """Solve the problem for a given graph"""
    # Build adjacency matrix
    adj = [[False] * n for _ in range(n)]

    for x, y in edges:
        adj[x - 1][y - 1] = True
