Looking at this problem, I need to find 3 internally vertex-disjoint paths between some pair of vertices in a graph. These paths must:
1. Start at the same vertex
2. End at the same vertex  
3. Have no common internal vertices (no blocking except start/end)
4. Each edge can be used at most once

Let me write an efficient solution that tries to find such paths.

```python
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())
    if n < 2 or m == 0:
        return "NO"

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, min(len(lines), m + 1)):
        if i >= len(lines):
            break
        u, v = map(int, lines[i].split())
        graph[u].append(v)
        graph[v].append(u)

    def find_three_paths(start, end):
        """Find 3 internally vertex-disjoint paths from start to end"""
        if start == end or len(graph[start]) == 0 or len(graph[end]) == 0:
            return None

        paths = []
        blocked = {start, end}

        for _ in range(3):
            queue = deque([(start, [start])])
            visited = {start}
            found_path = None

            while queue:
                node, path = queue.popleft()
                if node == end:
                    found_path = path
                    break

                for neighbor in graph[node]:
                    if neighbor not in visited and neighbor not in blocked:
                        visited.add(neighbor)
                        queue.append((neighbor, path + [neighbor]))

            if found_path is None:
                return None
            paths.append(found_path)
            # Block internal vertices for next path
            for node in found_path[1:-1]:
                blocked.add(node)

        return paths if len(paths) == 3 else None

    # Check all possible start-end pairs
    for start in range(1, n + 1):
        if not graph[start]:
            continue
        for end in range(1, n + 1):
            if start == end or not graph[end]:
                continue

            paths = find_three_paths(start, end)
            if paths:
                result = ["YES"]
                for p in paths:
                    result.append(f"{len(p)} {' '.join(map(str, p))}")
                return '\n'.join(result)

    return "NO"

if __name__ == "__main__":
    import sys
    input_data = sys.stdin.read()
    print(solution(input_data))
